import{j as e}from"./vendor-react-7UxssXty.js";import{P as a,m as o}from"./SiteLinks-Cj3fexfN.js";import{L as s}from"./LegalDoc-BM2K5zwa.js";import"./vendor-router-hNuEoVCG.js";import"./vendor-misc-CGJCdZM4.js";import"./PublicLayout-DW_I9I_O.js";/* empty css              */const r=[{h:"1. Responsable del tratamiento",p:"El responsable del tratamiento de los datos es Shopy Crafter, con domicilio en España. Puedes contactarnos en craftershopy@gmail.com para cualquier asunto relativo a tus datos personales."},{h:"2. Datos que recogemos",p:"Recopilamos los datos que tú nos facilitas (nombre, email, teléfono, URL de tienda, nicho, facturación aproximada) y datos técnicos básicos de navegación (IP anonimizada, navegador, páginas visitadas) para operar el servicio y mejorar la experiencia."},{h:"3. Finalidad",p:"Usamos tus datos exclusivamente para responder a tus solicitudes, prestar los servicios contratados, facturar, enviarte información sobre tu cuenta y, sólo si nos lo autorizas, comunicaciones comerciales sobre nuestros propios servicios."},{h:"4. Base legal",p:"Tratamos los datos con base en la ejecución del contrato (servicios contratados), tu consentimiento (formulario de contacto, newsletter) y nuestro interés legítimo en mantener la seguridad y mejorar el producto."},{h:"5. Conservación",p:"Conservamos tus datos mientras tengas una cuenta activa y, una vez cerrada, durante los plazos legales aplicables (fiscal, contable, defensa de reclamaciones). Después se eliminan o anonimizan."},{h:"6. Tus derechos",p:"Puedes ejercer tus derechos de acceso, rectificación, supresión, oposición, limitación y portabilidad escribiéndonos a craftershopy@gmail.com. Si no quedas satisfecho, puedes presentar reclamación ante la Agencia Española de Protección de Datos (aepd.es)."},{h:"7. Terceros",p:"No vendemos ni cedemos tus datos. Trabajamos con proveedores tecnológicos (hosting, IA, pagos) que actúan como encargados del tratamiento bajo contratos que cumplen con el RGPD."},{h:"8. Transferencias internacionales",p:"Cuando algún proveedor opere fuera del EEE, nos aseguramos de que existan garantías adecuadas (cláusulas contractuales tipo aprobadas por la Comisión Europea o decisión de adecuación)."},{h:"9. Medidas de seguridad",p:"Aplicamos cifrado en tránsito (TLS) y en reposo (AES-256), control de accesos por rol, copias de seguridad periódicas, registro de auditoría y revisiones de seguridad recurrentes."},{h:"10. Notificación de incidentes",p:"En caso de brecha de seguridad que pueda suponer riesgo para tus derechos, te lo notificaremos sin dilación y, cuando proceda, en un plazo máximo de 72 horas a la AEPD."}];function u(){return e.jsxs(e.Fragment,{children:[e.jsx(a,{...o("/privacidad")}),e.jsx(s,{current:"/privacidad",title:"Política de Privacidad",lead:"Qué datos tratamos, para qué, durante cuánto tiempo y cómo puedes ejercer tus derechos.",updated:"mayo 2026",sections:r})]})}export{u as default};
